# src/attention/StarAttention.jl
module StarAttention

using ..TensorCore
using LinearAlgebra
using Statistics

const BLOCK_SIZE = 512
const NUM_HOSTS = 8

struct StarAttentionLayer
    d_model::Int
    num_heads::Int
    head_dim::Int
    local_window::Int
    global_bias::Matrix{Float64}

    function StarAttentionLayer(;
        d_model::Int = 18432,
        num_heads::Int = 512,
        local_window::Int = BLOCK_SIZE
    )
        head_dim = d_model ÷ num_heads
        global_bias = zeros(Float64, num_heads, num_heads)
        new(d_model, num_heads, head_dim, local_window, global_bias)
    end
end

function phase1_local_attention(layer::StarAttentionLayer, x::Matrix{Float64}, block_id::Int)::Matrix{Float64}
    seq_len = size(x, 2) ÷ layer.d_model
    q = project(x, layer.q_proj)
    k = project(x, layer.k_proj)
    v = project(x, layer.v_proj)
    q_heads = reshape(q, :, seq_len, layer.num_heads, layer.head_dim)
    k_heads = reshape(k, :, seq_len, layer.num_heads, layer.head_dim)
    v_heads = reshape(v, :, seq_len, layer.num_heads, layer.head_dim)
    output = zeros(eltype(q), size(q))
    start_idx = block_id * BLOCK_SIZE + 1
    end_idx = min(start_idx + layer.local_window - 1, seq_len)
    for h in 1:layer.num_heads
        for i in start_idx:end_idx
            attn_scores = q_heads[:, i, h, :] * k_heads[:, start_idx:end_idx, h, :]' / sqrt(Float64(layer.head_dim))
            attn_weights = softmax(attn_scores, dims=2)
            output[:, i] += (attn_weights * v_heads[:, start_idx:end_idx, h, :])[:, :, 1]
        end
    end
    layer_norm(dropout(output + x))
end

function phase2_global_attention(layer::StarAttentionLayer, q::Matrix{Float64}, cached_kv::Tuple{Matrix{Float64}, Matrix{Float64}})::Matrix{Float64}
    k, v = cached_kv
    attn_scores = q * k' / sqrt(Float64(layer.d_model))
    attn_scores .+= layer.global_bias
    attn_weights = softmax(attn_scores, dims=2)
    output = attn_weights * v
    layer_norm(dropout(output))
end

function forward(layer::StarAttentionLayer, x::Matrix{Float64}, cached_kv::Tuple{Matrix{Float64}, Matrix{Float64}}, block_id::Int)::Tuple{Matrix{Float64}, Tuple{Matrix{Float64}, Matrix{Float64}}}
    local_out = phase1_local_attention(layer, x, block_id)
    q = project(local_out, layer.q_proj)
    k = project(local_out, layer.k_proj)
    v = project(local_out, layer.v_proj)
    new_k = hcat(cached_kv[1], k)
    new_v = hcat(cached_kv[2], v)
    global_out = phase2_global_attention(layer, q, cached_kv)
    (local_out + global_out, (new_k, new_v))
end

export StarAttentionLayer, forward

end
