// src/core/VecInferUltra.zig
const std = @import("std");
const math = std.math;

pub const VecInferUltra = struct {
    allocator: std.mem.Allocator,
    codebook: []f32,
    codebook_size: usize,
    bit_width: u8,
    smooth_param: f32,
    hadamard_matrix: ?[][]f32,

    pub fn init(allocator: std.mem.Allocator, codebook_size: usize, bit_width: u8) !VecInferUltra {
        var self = VecInferUltra{
            .allocator = allocator,
            .codebook = try allocator.alloc(f32, codebook_size * 128), // Assuming 128 dim
            .codebook_size = codebook_size,
            .bit_width = bit_width,
            .smooth_param = 0.1,
            .hadamard_matrix = null,
        };
        // Initialize codebook randomly
        var prng = std.rand.DefaultPrng.init(42);
        const rand = prng.random();
        for (self.codebook) |*val| {
            val.* = rand.floatNorm(f32);
        }
        try self.buildHadamardMatrix();
        return self;
    }

    pub fn deinit(self: *VecInferUltra) void {
        if (self.hadamard_matrix) |hm| {
            for (hm) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(hm);
        }
        self.allocator.free(self.codebook);
    }

    fn buildHadamardMatrix(self: *VecInferUltra) !void {
        const dim = 128; // Fixed dim
        var hm = try self.allocator.alloc([]f32, dim);
        for (hm) |*row, i| {
            row.* = try self.allocator.alloc(f32, dim);
            for (row.*, 0..) |*val, j| {
                if (i == j) {
                    val.* = 1.0;
                } else if ((i ^ j).countTrailingZeros() % 2 == 0) {
                    val.* = 1.0;
                } else {
                    val.* = -1.0;
                }
            }
        }
        self.hadamard_matrix = hm;
    }

    pub fn compressKV(self: *VecInferUltra, kv: []f32) ![]u8 {
        const dim = 128;
        const seq_len = kv.len / dim;
        var compressed = try self.allocator.alloc(u8, seq_len * (self.bit_width / 8 + 1));
        for (0..seq_len) |i| {
            const slice = kv[i * dim .. (i + 1) * dim];
            var smoothed = try self.applySmooth(slice);
            var transformed = try self.applyHadamard(smoothed);
            const indices = try self.vectorQuantize(transformed);
            const packed = self.packBits(indices);
            @memcpy(compressed[i * (self.bit_width / 8 + 1) ..], &packed);
        }
        return compressed;
    }

    fn applySmooth(self: *VecInferUltra, input: []const f32) ![]f32 {
        var smoothed = try self.allocator.alloc(f32, input.len);
        const mean = std.mem.mean(f32, input);
        for (smoothed, 0..) |*val, i| {
            val.* = input[i] + self.smooth_param * (mean - input[i]);
        }
        return smoothed;
    }

    fn applyHadamard(self: *VecInferUltra, input: []const f32) ![]f32 {
        if (self.hadamard_matrix == null) return input;
        const hm = self.hadamard_matrix.?;
        var output = try self.allocator.alloc(f32, input.len);
        for (output, 0..) |*val, i| {
            val.* = 0.0;
            for (input, 0..) |in_val, j| {
                val.* += in_val * hm[i][j];
            }
        }
        return output;
    }

    fn vectorQuantize(self: *VecInferUltra, input: []const f32) ![]u8 {
        var indices = try self.allocator.alloc(u8, self.codebook_size);
        for (indices, 0..) |*idx, i| {
            var min_dist: f32 = std.math.f32_max;
            for (0..self.codebook_size) |cb_i| {
                const cb_start = cb_i * 128;
                var dist: f32 = 0.0;
                for (0..128) |d| {
                    const diff = input[d] - self.codebook[cb_start + d];
                    dist += diff * diff;
                }
                if (dist < min_dist) {
                    min_dist = dist;
                    idx.* = @intCast(cb_i);
                }
            }
        }
        return indices;
    }

    fn packBits(self: *VecInferUltra, indices: []const u8) u64 {
        var packed: u64 = 0;
        for (indices, 0..) |idx, i| {
            packed |= (@as(u64, idx) << (i * self.bit_width));
        }
        return packed;
    }

    pub fn decompressKV(self: *VecInferUltra, compressed: []const u8) ![]f32 {
        const dim = 128;
        const seq_len = compressed.len / (self.bit_width / 8 + 1);
        var kv = try self.allocator.alloc(f32, seq_len * dim);
        for (0..seq_len) |i| {
            const packed = std.mem.readIntLittle(u64, compressed[i * (self.bit_width / 8 + 1) ..]);
            const indices = self.unpackBits(packed);
            const slice = kv[i * dim .. (i + 1) * dim];
            try self.dequantizeTo(indices, slice);
            var smoothed = try self.inverseSmooth(slice);
            _ = try self.inverseHadamard(smoothed);
        }
        return kv;
    }

    fn unpackBits(self: *VecInferUltra, packed: u64) []u8 {
        var indices = self.allocator.alloc(u8, self.codebook_size) catch unreachable;
        for (indices, 0..) |*idx, i| {
            idx.* = @intCast((packed >> (i * self.bit_width)) & ((1 << self.bit_width) - 1));
        }
        return indices;
    }

    fn dequantizeTo(self: *VecInferUltra, indices: []const u8, output: []f32) !void {
        for (0..128) |d| {
            output[d] = 0.0;
            for (indices, 0..self.codebook_size) |idx, i| {
                const cb_start = idx * 128;
                output[d] += self.codebook[cb_start + d] / @as(f32, self.codebook_size);
            }
        }
    }

    fn inverseSmooth(self: *VecInferUltra, input: []f32) ![]f32 {
        var original = try self.allocator.alloc(f32, input.len);
        const mean = std.mem.mean(f32, input);
        for (original, 0..) |*val, i| {
            val.* = input[i] / (1.0 + self.smooth_param) + self.smooth_param * mean / (1.0 + self.smooth_param);
        }
        return original;
    }

    fn inverseHadamard(self: *VecInferUltra, input: []f32) !void {
        if (self.hadamard_matrix == null) return;
        const hm = self.hadamard_matrix.?;
        const dim = input.len;
        var temp = try self.allocator.alloc(f32, dim);
        for (temp, 0..) |*val, i| {
            val.* = 0.0;
            for (input, 0..) |in_val, j| {
                val.* += in_val * hm[j][i]; // Transpose
            }
            val.* /= @as(f32, dim);
        }
        @memcpy(input, temp);
        self.allocator.free(temp);
    }
};

pub fn outlierGating(kv: []f32, threshold: f32) []f32 {
    var gated = kv;
    for (gated) |*val| {
        if (@abs(val.*) > threshold) {
            val.* = threshold * @copysign(1.0, val.*);
        }
    }
    return gated;
}
