# src/core/NSRDeltaCache.jl
module NSRDeltaCache

using ..TensorCore
using LinearAlgebra

const SEGMENT_SIZE = 1024
const DELTA_THRESHOLD = 0.01

struct DeltaCacheEntry
    segment_id::Int
    delta_matrix::Matrix{Float64}
    timestamp::Float64
end

struct NeuralSegmentRouter
    cache::Dict{Int, DeltaCacheEntry}
    routing_table::Matrix{Int}
    memory_dim::Int
    allocator::Any

    function NeuralSegmentRouter(memory_dim::Int = 16384)
        new(Dict{Int, DeltaCacheEntry}(), zeros(Int, memory_dim, memory_dim), memory_dim, nothing)
    end
end

function route(router::NeuralSegmentRouter, query::Vector{Float64})::Vector{Int}
    scores = router.routing_table * query
    segments = argmax.(eachrow(scores), dims=1)
    segments
end

function update_delta_cache(router::NeuralSegmentRouter, segment_id::Int, update::Matrix{Float64})
    entry = get!(router.cache, segment_id, DeltaCacheEntry(segment_id, zeros(size(update)), time()))
    new_delta = update - entry.delta_matrix
    if norm(new_delta) > DELTA_THRESHOLD
        entry.delta_matrix += new_delta * 0.1
        entry.timestamp = time()
    end
    entry
end

function apply_delta_cache(entry::DeltaCacheEntry, base::Matrix{Float64})::Matrix{Float64}
    base + entry.delta_matrix
end

function forward(router::NeuralSegmentRouter, input::Matrix{Float64})::Matrix{Float64}
    seq_len, _ = size(input)
    segments = Int[]
    for i in 1:SEGMENT_SIZE:size(input, 1)
        seg = input[i:min(i+SEGMENT_SIZE-1, seq_len), :]
        q = mean(seg, dims=1)[:]
        seg_ids = route(router, q)
        append!(segments, seg_ids)
        for id in unique(seg_ids)
            update_delta_cache(router, id, seg)
        end
    end
    output = zeros(size(input))
    pos = 1
    for i in 1:SEGMENT_SIZE:seq_len
        end_pos = min(i + SEGMENT_SIZE - 1, seq_len)
        seg = input[i:end_pos, :]
        for j in 1:size(seg, 1)
            id = segments[pos]
            entry = router.cache[id]
            output[i+j-1, :] = apply_delta_cache(entry, seg[j, :]')
        end
        pos += size(seg, 1)
    end
    output
end

export NeuralSegmentRouter, forward

end
